const canim={t:'metin',title:'Canım Kitap',by:'Metnin özeti (Suut Kemal Yetkin)',text:'Yazar, bir zamanlar Fransa’da sıkça sorulan "Issız bir adaya hangi kitapları götürürdünüz?" sorusundan yola çıkar. İnsanların kalabalık içinde bile yalnız olduğunu, bu yalnızlığı en iyi kitapların giderdiğini söyler. Ona göre hiçbir dost insana kitaptan daha yakın değildir. Dışarı çıkarken yanına hep küçük bir kitap alır. Sonunda adaya gitmek istemediğini, kitaplarının arasında, odasında daha mutlu olduğunu belirtir.'};
const medya={t:'metin',title:'Medya Okuryazarlığı',by:'Metnin özeti (RTÜK Medya ve Çocuk)',text:'Kitaplar, televizyon, internet, oyunlar ve sosyal medya gibi tüm ortamlar medyadır. Medya okuryazarı olmak, bu içerikleri doğru kullanabilmektir. Bunun için bir dedektif gibi uyanık olmalıyız; çünkü içerikleri hazırlayanların para kazanma amacı olabilir ve her bilgi doğru olmayabilir. Emin olmadığımız bilgileri büyüklerimize ve bilen kişilere sormalıyız.'};
const paylasim={t:'gazete',title:'Sosyal medyada bir paylaşım',by:'Örnek metin',text:'ŞOK! Her gün bir saat kitap okuyan çocukların boyu bir yılda iki kat uzuyor! Kaynağını sormayın, hemen paylaşın, herkes duysun!'};
FEN.lesson({id:'5-5',t:'Canım Kitap ve Tema Değerlendirme',p:'109–115',kw:'Canım Kitap serbest okuma medya okuryazarlığı bakış açısı eleştiri Türkçe Orhun Yazıtları kültür okuryazarlığı değerlendirme',script:[
 ['Görev','Bu derste kitabı can dostu bilen bir yazarın düşüncelerini okuyacak, medya okuryazarlığını öğrenecek ve temayı tekrar edeceğiz.',[['title','Canım Kitap ve Değerlendirme','s. 109–115'],['txt','Issız bir adaya hangi kitapları götürürdün?',300,' st-gold']]],
 ['Metin','Yazar, ıssız adaya hangi kitapları götürürdünüz sorusundan yola çıkar. İnsanların kalabalıkta bile yalnız olduğunu, bu yalnızlığı kitapların giderdiğini söyler. Ona göre hiçbir dost insana kitaptan daha yakın değildir.',[['source',{t:'metin',title:'Canım Kitap',by:'Metnin özeti (Suut Kemal Yetkin)',text:'Yazara göre insan kalabalıkta bile yalnızdır ve bu yalnızlığı en iyi kitaplar giderir. Hiçbir dost insana kitaptan daha yakın değildir.'},['yalnızlığı','kitaptan daha yakın']]]],
 ['Medya','Kitap, televizyon, internet, oyun ve sosyal medya; hepsi medyadır. İyi bir medya okuryazarı bir dedektif gibi davranır. Bilgiyi kimin paylaştığına, kaynağın güvenilir olup olmadığına ve içeriğin duygularımızı kışkırtıp kışkırtmadığına bakar.',[['chain',[['👤','Kim paylaştı?'],['🔎','Kaynak sağlam mı?'],['🎯','Amacı ne?'],['😠','Duyguya mı oynar?'],['🧑‍🏫','Bilene danış']],220]]],
 ['Bakış','Aynı medya içeriğine farklı kişiler farklı açılardan bakar. Okur eğlenmek ister, üretici satmak ister, ebeveyn ise çocuğunu korumak ister.',[['cards',[['🎮','Okur','Oynamak, izlemek ister'],['💰','Üretici','Satmak, kazanmak ister'],['👪','Ebeveyn','Korumak ister']]]]],
 ['Türkçe','Türkçenin bilinen en eski yazılı belgeleri sekizinci yüzyıldaki Orhun Yazıtlarıdır. On birinci yüzyılda Kutadgu Bilig ve Divanü Lügati’t-Türk yazıldı. Bin dokuz yüz yirmi sekizde Harf Devrimi yapıldı, bin dokuz yüz otuz ikide Türk Dil Kurumu kuruldu.',[['timeline',[[732,'Kül Tigin Yazıtı'],[1070,'Kutadgu Bilig'],[1074,'Divanü Lügati’t-Türk'],[1928,'Harf Devrimi'],[1932,'Türk Dil Kurumu']]]]],
 ['Tuzak','Dikkat! Büyük harfle yazılmış, ünlem dolu bir paylaşım doğru olduğu için değil, dikkat çekmek için böyle yazılmış olabilir. Önce kaynağı sorgula.',[['trap','Çok paylaşılan bilgi doğru bilgi demek değildir.'],['tip','Kaynağı sor, araştır, sonra karar ver.']]],
 ['Özet','Temayı toparlayalım.',[['rules',['Kitap, insanın en yakın dostudur','Medyada dedektif ol: kaynağı sorgula','Bakış açısı değişince yorum da değişir','Eleştiri: konu, ölçüt, yargı, gerekçe','Önemli bilgi + sıra + kendi sözün = özet'],110]]]],
 q:[
  {k:'src',src:canim,p:'Metnin ana fikri hangisidir?',a:'Kitap, insanın en yakın ve en vazgeçilmez dostudur.',w:[['Fransa’da eskiden anketler yapılırdı.','u5_fikir'],['Issız bir adada yaşamak zordur.','u5_fikir']],e:'Anket sorusu yalnızca bir giriştir; yazarın asıl mesajı kitabın insanın en yakın dostu olduğudur.'},
  {k:'src',src:canim,p:'Yazar neden dışarı çıkarken yanına küçük bir kitap alır?',a:'Kalabalıkta bile insanın içine yalnızlık çökebileceği için',w:[['Kitap satmak istediği için','u5_cikarim'],['Bir ankete katılacağı için','u5_cikarim']],e:'Yazara göre insan kalabalıkta da yalnız kalabilir; kitap o an en iyi yoldaştır.'},
  {k:'src',src:canim,p:'Metin nasıl bir anlatımla yazılmıştır?',a:'Yazarın duygu ve düşüncelerini anlattığı öznel bir anlatımla',w:[['Yalnızca sayılara dayanan nesnel bir anlatımla','u5_yol'],['Bir masal anlatıcısının ağzından','u5_yol']],e:'Yazar "bence", "severim" gibi ifadelerle kendi düşüncelerini ve duygularını anlatıyor.'},
  {k:'src',src:medya,p:'Metne göre medyaya karşı neden bir dedektif gibi davranmalıyız?',a:'Medyadaki her bilgi doğru ve uygun olmayabilir.',w:[['Medya yalnızca suç haberleri verir.','u5_cikarim'],['Dedektiflik bir meslek olarak önerilir.','u5_san']],e:'Metin, içerikleri hazırlayanların para kazanma amacı olabileceğini ve her bilginin doğru olmayabileceğini söylüyor.'},
  {k:'src',src:medya,p:'Metinde ele alınan problem hangisidir?',a:'Medya içeriklerinin her zaman doğru ve uygun olmaması',w:[['İnternetin yavaş çalışması','u5_cikarim'],['Kitapların pahalı olması','u5_cikarim']],e:'Metnin odaklandığı sorun, medya içeriklerine sorgulamadan güvenilmesidir.'},
  {k:'src',src:paylasim,p:'Medya okuryazarı biri bu paylaşıma nasıl yaklaşır?',a:'Kaynağını sorgular, inanmadan önce araştırır.',w:[['Hemen paylaşır, herkes duysun ister.','u5_cikarim'],['Büyük harfle yazıldığı için doğru sayar.','u5_cikarim']],e:'Kaynağı belirsiz, duyguları kışkırtan ve "hemen paylaş" diyen içerikler sorgulanmalıdır.'},
  {k:'listen',text:'Türkçenin bilinen en eski yazılı belgeleri, sekizinci yüzyılda dikilen Orhun Yazıtlarıdır. On birinci yüzyılda Yusuf Has Hacip Kutadgu Bilig’i, Kâşgarlı Mahmut ise Divanü Lügati’t-Türk’ü yazdı. Yüzyıllar içinde Türkçe değişti ve zenginleşti. Ama bu eserler bugün de dilimizin köklerini gösteriyor.',p:'Konuşmaya göre Türkçenin bilinen en eski yazılı belgeleri hangileridir?',a:'Orhun Yazıtları',w:[['Kutadgu Bilig','u5_cikarim'],['Divanü Lügati’t-Türk','u5_cikarim']],e:'Kutadgu Bilig ve Divanü Lügati’t-Türk on birinci yüzyıldandır; Orhun Yazıtları ise sekizinci yüzyıldan.'},
  {k:'tl',p:'Türkçenin yolculuğundaki olayları zaman sırasına diz.',ev:[[732,'Kül Tigin Yazıtı'],[1070,'Kutadgu Bilig'],[1074,'Divanü Lügati’t-Türk'],[1928,'Harf Devrimi'],[1932,'Türk Dil Kurumu kuruldu']],mis:'other',e:'Orhun Yazıtları sekizinci, Kutadgu Bilig ve Divanü Lügati’t-Türk on birinci yüzyıldandır; Harf Devrimi 1928’de yapıldı, Türk Dil Kurumu 1932’de kuruldu.'},
  {k:'mc',p:'"Kütüphanede epey vakit geçirdim." cümlesindeki zarf hangi türdendir?',a:'Miktar zarfı',w:[['Yer-yön zarfı','u5_zarf'],['Durum zarfı','u5_zarf']],e:'"Ne kadar vakit geçirdim?" sorusunun cevabı "epey"dir; bu miktar zarfıdır.'},
  {k:'mc',p:'Hangi seçenek yazım bakımından doğrudur?',a:'Kitapları öğrencilere beşer beşer dağıttık.',w:[['Kitapları öğrencilere 5’er 5’er dağıttık.','u5_yaz'],['Kitapları öğrencilere beşerbeşer dağıttık.','u5_yaz']],e:'Üleştirme sayıları yazıyla ve tekrar edildiğinde ayrı yazılır: beşer beşer.'},
  {k:'hunt',p:'Durum zarfını bul.',s:'Kardeşim akşamları kitabını sessizce okur.',bad:[3],fixed:'"Nasıl okur?" sorusunun cevabı "sessizce"dir; durum zarfıdır. "akşamları" ise zaman zarfıdır.',mis:'u5_zarf',e:'Durum zarfı, fiilin nasıl yapıldığını bildirir.'},
  {k:'hunt',p:'Cümledeki yazım yanlışını bul.',s:'Medya da gördüğümüz her bilgi doğru olmayabilir.',bad:[1],fixed:'Medyada gördüğümüz her bilgi doğru olmayabilir.',mis:'u5_yaz',e:'Burada "-da" bulunma ekidir ve kelimeye bitişik yazılır. Bağlaç olan "da" ise ayrı yazılır.'},
  {k:'split',p:'Kelimeyi kök ve eklerine ayır.',word:'okuryazarlık',parts:['oku','r','yaz','ar','lık'],mis:'u5_ek',e:'okur (oku + r) ve yazar (yaz + ar) birleşir, sonuna -lık yapım eki gelir.'},
  {k:'ek',p:'"Götürürsünüz" kelimesini parçaları birleştirerek kur.',parts:['götür','ür','sünüz'],extra:['ur','sunuz'],info:['kök','geniş zaman eki','2. çoğul kişi eki'],mis:'u5_ek',e:'götür + ür + sünüz: ünlü uyumu gereği ekler "ü" ile kurulur.'},
  {k:'tf',p:'Bir bilginin güvenilir olup olmadığını anlamak için onu kimin paylaştığına bakmak önemlidir.',a:true,mis:'u5_cikarim',e:'Medya okuryazarı, bilginin kaynağını ve paylaşanın güvenilirliğini sorgular.'},
  {k:'para',p:'Cümleleri sıralayarak eleştirel bir paragraf oluştur.',items:['Kitap öneri listeleri, birçok okulda okuma için tek rehber olarak kullanılıyor.','Oysa iyi bir okurun ölçütü, kendi ilgisine göre kitap seçebilmesidir.','Bu açıdan bakınca yalnızca listeye bağlı kalmak okuru sınırlıyor.','Bu nedenle listeler bir başlangıç olmalı, öğrenciler kendi seçimlerini de eklemelidir.'],mis:'u5_yol',e:'Sorgulanan durum, ölçütle karşılaştırma, yargı ve gerekçeli çözüm sırası izlenir.'},
  {k:'sc',role:'Sınıf grubuna doğruluğu belirsiz, korkutucu bir haber atıldı. Herkes paylaşmaya başladı.',steps:[{p:'Ne yaparsın?',o:[['Paylaşmadan önce haberin kaynağını araştırırım',2,'Medya okuryazarı önce sorgular, sonra karar verir.'],['Ben de hemen paylaşırım',0,'Yanlış bilgi yayarak başkalarını da korkutabilirsin.','u5_cikarim'],['Hiç bakmadan görmezden gelirim',1,'Paylaşmadın ama arkadaşlarını uyarma fırsatını kaçırdın.']]},{p:'Haberin uydurma olduğunu buldun. Şimdi ne yaparsın?',o:[['Gruba nazikçe güvenilir kaynağı paylaşırım',2,'Kimseyi suçlamadan doğruyu göstermek en iyi yoldur.'],['Paylaşanlarla alay ederim',0,'Alay etmek kimseye bir şey öğretmez, kırar.']]}],e:'Bilgiyi sorgulamak ve doğrusunu kibarca paylaşmak medya okuryazarlığının özüdür.'},
  {k:'sc',role:'Sınıfınıza farklı bir ülkeden yeni bir öğrenci geldi. Türkçeyi yeni öğreniyor ve teneffüste yalnız kalıyor.',steps:[{p:'Ne yaparsın?',o:[['Yanına gidip kendimi tanıtır, oyuna davet ederim',2,'Empati kurmak ve onu aramıza katmak kültür okuryazarlığının göstergesidir.'],['Konuşmasıyla dalga geçenlere katılırım',0,'Bu kırıcı bir davranıştır; farklılıklara saygı göstermeliyiz.','u5_cikarim'],['Başkası ilgilenir diye beklerim',1,'İyi niyetlisin ama ilk adımı atmak çok değerlidir.']]},{p:'Ona Türkçe öğrenmesinde nasıl yardım edersin?',o:[['Birlikte resimli bir çocuk kitabı okumayı öneririm',2,'Kitaplar dil öğrenmenin ve dostluğun en güzel köprüsüdür.'],['Kendi kendine öğrenir derim',0,'Desteğe ihtiyacı olan birini yalnız bırakmış olursun.']]}],e:'Kültür okuryazarı kişi farklılıklara saygı duyar, empati kurar ve ilk adımı atmaktan çekinmez.'}],
 write:{title:'Öneri listeleri: Eleştiri paragrafı',prompt:'"Kitap öneri listeleri okuma kültürünü zenginleştirir mi, yoksa sınırlar mı?" sorusu üzerine eleştirel bir paragraf yaz. Durumu belirt, bir ölçütle karşılaştır, yargına ulaş ve gerekçeli bir çözüm öner.',tips:['Sorgulanan durumu açıkça yaz','Bir ölçüt seç ve durumu onunla karşılaştır','Olumlu ya da olumsuz yargını belirt','Gerekçeli bir çözüm önerisiyle bitir'],min:60}});
